function socialOverviewV551(cid,month,items){
  let client=cl(cid)||{},plan=(D.plans||[]).find(row=>row.client_id===cid&&dateMonth(row.month)===month),stages=socialWorkflowStagesV550(),pending=items.filter(item=>['approval','changes_requested'].includes(item.status)),dated=items.filter(item=>item.publication_date).slice().sort((a,b)=>String(a.publication_date).localeCompare(String(b.publication_date))),todayValue=today(),upcoming=dated.filter(item=>item.publication_date>=todayValue).slice(0,4),featured=(upcoming.length?upcoming:dated.slice(-4)).slice(0,4),report=socialReportsV550(cid).find(row=>dateMonth(row.period)===month)||socialReportsV550(cid).at(-1);
  return `<div class="v551-overview"><section class="v551-overview-hero"><div><small class="ey">VISÃO GERAL · ${E(portalMonthNameV428(month))}</small><h2>${E(plan?.theme||client.objective||'A presença da marca tomando forma.')}</h2><p>${E(plan?.main_goal||'Estratégia, produção, aprovações, calendário e resultados conectados em uma única leitura.')}</p></div><button class="btn ghost" data-cmode="feed">Ver prévia do feed</button></section><section class="panel v551-progress"><div class="head"><div><small class="ey">FLUXO DO MÊS</small><h3>Onde cada conteúdo está</h3></div><button class="btn ghost small" data-cmode="workflow">Abrir workflow →</button></div><div class="v551-stage-line">${stages.map(stage=>{let count=items.filter(item=>stage.statuses.includes(item.status)).length;return`<button data-cmode="workflow" class="stage-${stage.key}"><i></i><span>${E(stage.label)}</span><b>${count}</b></button>`}).join('')}</div></section><div class="v551-overview-grid"><section class="panel v551-next"><div class="head"><div><small class="ey">CONTEÚDOS EM FOCO</small><h3>${featured.length?'O visual do mês':'O planejamento começa aqui'}</h3></div><button class="btn ghost small" data-cmode="calendar">Ver calendário</button></div><div class="v551-cover-row">${featured.map(item=>`<article data-contentopen="${item.id}">${socialAssetV550(item)}<div><small>${item.publication_date?fmtDate(item.publication_date):'SEM DATA'} · ${E(fmt(item.format||'static_post'))}</small><b>${E(item.title||'Conteúdo')}</b><span class="st-${socialStatusClassV550(item.status)}">${E(socialStatusLabelV550(item.status))}</span></div></article>`).join('')||'<div class="v550-empty-state">Adicione o primeiro conteúdo para construir esta visão.</div>'}</div></section><aside class="v551-side"><section class="panel v551-attention"><small class="ey">APROVAÇÕES</small><h3>${pending.length?`${pending.length} ${pending.length===1?'item pede':'itens pedem'} atenção`:'Tudo em dia'}</h3><p>${pending.length?'Revise o que aguarda retorno ou voltou com ajustes.':'Nenhum conteúdo está parado nesta etapa.'}</p><button class="btn ${pending.length?'pri':'ghost'} small" data-cmode="approvals">Abrir aprovações</button></section><section class="panel v551-result-glance"><small class="ey">ÚLTIMO FECHAMENTO</small>${report?`<h3>${socialCompactV550(report.reach)} de alcance</h3><p>Engajamento de ${Number(report.engagement_rate||0).toLocaleString('pt-BR',{minimumFractionDigits:1,maximumFractionDigits:2})}% no período.</p>`:'<h3>Resultados em construção</h3><p>O relatório mensal ganha vida assim que as métricas forem cadastradas.</p>'}<button class="btn ghost small" data-cmode="results">Ver resultados</button></section></aside></div></div>`
}
function socialApprovalsV551(cid,month,items){
  let itemIds=new Set(items.map(item=>item.id)),rows=(D.approvals||[]).filter(row=>itemIds.has(row.content_id)).slice().sort((a,b)=>String(b.created_at||'').localeCompare(String(a.created_at||''))),pending=rows.filter(row=>row.status==='pending'),changes=items.filter(item=>item.status==='changes_requested'),activeIds=new Set([...pending.map(row=>row.content_id),...changes.map(item=>item.id)]),active=items.filter(item=>activeIds.has(item.id)),history=rows.filter(row=>row.status!=='pending').slice(0,6);
  return `<div class="v551-approvals"><section class="v551-approval-hero"><div><small class="ey">APROVAÇÕES · ${E(portalMonthNameV428(month))}</small><h2>Peça, texto e decisão<br>no mesmo lugar.</h2><p>Veja rapidamente o que aguarda revisão, o que voltou para ajustes e o que já pode seguir.</p></div><span>${active.length?`${active.length} EM ANDAMENTO`:'FLUXO EM DIA'}</span></section><section class="panel v551-approval-list"><div class="head"><div><small class="ey">EM ANDAMENTO</small><h3>${active.length?'Conteúdos que pedem atenção':'Tudo aprovado por aqui ✨'}</h3></div></div>${active.map(content=>{let info=approvalInfo(content),approval=rows.find(row=>row.content_id===content.id&&row.status==='pending'),buttonAction=approval?`data-ap="${approval.id}"`:`data-contentopen="${content.id}"`;return`<article data-contentopen="${content.id}">${socialAssetV550(content)}<div class="grow"><small>${content.publication_date?fmtDate(content.publication_date):'SEM DATA'} · ${E(fmt(content.format||'static_post'))}</small><h3>${E(content.title||'Conteúdo')}</h3><p>${E(String(content.caption||content.notes||'Abra o conteúdo para revisar os detalhes.').slice(0,180))}</p><span class="tag ${info.cls}">${E(info.label)}</span></div><button class="btn ${approval?'pri':'ghost'} small" ${buttonAction}>${approval?'Revisar':'Abrir conteúdo'}</button></article>`}).join('')||'<div class="v550-empty-state">Nenhum conteúdo aguardando aprovação ou ajustes neste mês.</div>'}</section>${history.length?`<section class="panel v551-history"><div class="head"><div><small class="ey">HISTÓRICO RECENTE</small><h3>Decisões registradas</h3></div></div>${history.map(row=>{let content=items.find(item=>item.id===row.content_id)||row.contents||{};return`<div class="row"><span class="dot ${row.status==='approved'?'g':'r'}"></span><div class="grow"><b>${E(content.title||'Conteúdo')}</b><small>${row.status==='approved'?'Aprovado':'Alteração solicitada'}</small></div><span class="tag ${row.status==='approved'?'g':'r'}">${row.status==='approved'?'Aprovado':'Ajustes'}</span></div>`}).join('')}</section>`:''}</div>`
}
function socialInternalContentPageV551(){
  let socialClients=(D.clients||[]).filter(row=>row.active&&hasClientService(row.id,'social_media'));if(!socialClients.some(row=>row.id===contentClient)&&socialClients[0])contentClient=socialClients[0].id;
  if(!['overview','strategy','workflow','calendar','approvals','results','feed'].includes(contentMode))contentMode='overview';
  let items=socialMonthItemsV550(contentClient,contentMonth),client=cl(contentClient)||{},modeLabel={overview:'Visão geral',strategy:'Estratégia',workflow:'Workflow',calendar:'Calendário',approvals:'Aprovações',results:'Resultados'},body;
  if(contentMode==='overview')body=socialOverviewV551(contentClient,contentMonth,items);
  else if(contentMode==='strategy')body=socialStrategyV550(contentClient,contentMonth,items,true);
  else if(contentMode==='workflow')body=socialWorkflowV550(items,false);
  else if(contentMode==='calendar')body=`<section class="panel v550-calendar-panel"><div class="head"><div><small class="ey">CALENDÁRIO EDITORIAL</small><h2>O mês com as peças no lugar.</h2></div><span class="tag">${items.filter(item=>item.publication_date).length} com data</span></div>${socialVisualCalendarV550(items,contentMonth,false)}${items.some(item=>!item.publication_date)?`<div class="v550-undated"><b>Sem data definida</b>${items.filter(item=>!item.publication_date).map(item=>`<button data-contentopen="${item.id}">${E(item.title)}</button>`).join('')}</div>`:''}</section>`;
  else if(contentMode==='approvals')body=socialApprovalsV551(contentClient,contentMonth,items);
  else if(contentMode==='results')body=socialResultsV550(contentClient,contentMonth,false,true);
  else body=`<section class="panel v551-feed"><div class="head"><div><small class="ey">PRÉVIA AUXILIAR</small><h2>Simulação do feed</h2></div><button class="btn ghost small" data-cmode="overview">← Voltar à visão geral</button></div>${feedPreviewGrid(items,false)}</section>`;
  return `<section class="v550-content-head"><div><small class="ey">SOCIAL MEDIA · ${E(client.name||'CLIENTE')}</small><h2>Estratégia, criação e resultado<br>no mesmo fluxo.</h2></div><div class="content-toolbar-actions"><button class="btn pri" data-m="contentNew">＋ Novo conteúdo</button><button class="btn ghost" data-clientlinks-v433="${contentClient}">Links da cliente</button></div></section><div class="v550-content-controls"><div class="filters"><select id="contentClient">${socialClients.map(row=>`<option value="${row.id}" ${contentClient===row.id?'selected':''}>${E(row.name)}</option>`).join('')}</select><input id="contentMonth" type="month" value="${contentMonth}"></div><nav class="v550-content-tabs">${Object.entries(modeLabel).map(([key,label])=>`<button data-cmode="${key}" class="${contentMode===key?'on':''}">${label}</button>`).join('')}</nav></div>${body}`
}
