function muralProfilesV555(){
  let membershipIds=new Set((D.teamMemberships||[]).filter(item=>item.role==='team').map(item=>item.user_id));
  let statusIds=new Set((D.teamStatuses||[]).map(item=>item.user_id));
  let rows=(D.profiles||[]).filter(person=>membershipIds.has(person.user_id));
  if(rows.length<2)rows=(D.profiles||[]).filter(person=>membershipIds.has(person.user_id)||statusIds.has(person.user_id));
  return rows.slice().sort((a,b)=>String(a.display_name||'').localeCompare(String(b.display_name||''),'pt-BR'));
}
function muralStatusTimeV555(value){if(!value)return'Status ainda não definido';let label=notificationWhen(value);return label==='agora'?'Atualizado agora':`Atualizado ${label}`}
teamStatusStrip=function(){
  let sts=D.teamStatuses||[],people=muralProfilesV555(),me=sts.find(item=>item.user_id===S.user.id);
  let cards=people.map(person=>{
    let status=sts.find(item=>item.user_id===person.user_id),meta=teamStatusMeta(status?.status_key),label=status?.status_text||meta[0],emoji=status?.emoji||meta[1],viewed=(status?.photo_viewed_by||[]).includes(S.user.id),hasPhoto=!!status?.photo_path&&!viewed,isMe=person.user_id===S.user.id;
    return `<article class="v555-person ${isMe?'is-me':''}"><button type="button" class="status-bubble ${hasPhoto?'has-photo':''}" ${hasPhoto?`data-statusphoto="${status.id}"`:''} aria-label="${hasPhoto?'Abrir foto de '+E(person.display_name):'Status de '+E(person.display_name)}"><span>${E(ini(person.display_name))}</span>${hasPhoto?'<i>1×</i>':''}</button><div class="v555-person-copy"><div><b>${E(person.display_name)}</b>${isMe?'<em>VOCÊ</em>':''}</div><strong>${E(emoji)} ${E(label)}</strong><small>${E(muralStatusTimeV555(status?.updated_at))}</small></div>${isMe?'<button type="button" class="v555-edit-status" data-v555-status-edit>Atualizar</button>':''}</article>`
  }).join('');
  return `<section class="v555-team-zone"><div class="v555-team-head"><div><small class="ey">AGORA NA COLAB</small><h2>Thalia + Carol</h2><p>O que cada uma está fazendo, sem ocupar a tela inteira.</p></div><span class="v555-sync"><i></i> Sincronizado automaticamente</span></div><div class="v555-people-grid">${cards||'<div class="v5-empty-soft">A equipe aparecerá aqui assim que o acesso for confirmado.</div>'}</div><details class="status-editor v555-status-editor"><summary>${me?'Atualizar meu status':'Definir meu status'}</summary><form id="teamStatusForm"><div class="status-form-grid"><div class="field"><label>Modo</label><select name="status_key">${[['on','Modo Colab: ON'],['creating','Em criação'],['hands_on','Mão na massa'],['coffee','Hora do café'],['break','No intervalo'],['capture','Em captação'],['focus','Foco total'],['done','Por hoje, concluído'],['custom','Personalizado']].map(([value,label])=>`<option value="${value}" ${me?.status_key===value?'selected':''}>${label}</option>`).join('')}</select></div><div class="field"><label>Escrever algo (opcional)</label><input name="status_text" maxlength="80" value="${E(me?.status_text||'')}" placeholder="Ex.: finalizando o calendário"></div><div class="field status-photo-field"><label>Foto do momento · visualização única</label><input id="statusPhotoInput" name="photo" type="file" accept="image/*"><small class="muted">Quando a outra pessoa abrir, a foto some para ela.</small></div></div><div class="actions"><button class="btn pri">Salvar status</button>${me?.photo_path?'<button type="button" class="btn ghost" data-statusclearphoto>Remover foto</button>':''}</div></form></details></section>`
};
muralPage=function(){
  let people=muralProfilesV555(),all=D.muralNotes||[],active=all.filter(item=>!item.resolved),done=all.filter(item=>item.resolved).slice(0,12);
  return `${teamStatusStrip()}<section class="v555-mural-toolbar"><div><small class="ey">RECADOS DA EQUIPE</small><h2>Mural compartilhado</h2><p>Status e post-its são atualizados para as duas automaticamente.</p></div><details class="mural-create"><summary>＋ Novo post-it</summary><form id="muralForm" class="mural-form"><div class="mural-form-grid"><div class="field mural-message"><label>Recado</label><textarea name="body" rows="3" maxlength="500" required placeholder="Carol, lembra de... / ideia aleatória / isso aqui é de milhões 👀"></textarea></div><div class="field"><label>Para quem?</label><select name="recipient_id"><option value="">Todo mundo</option>${people.map(person=>`<option value="${person.user_id}">${E(person.display_name)}</option>`).join('')}</select></div><div class="field"><label>Adesivo</label><select name="emoji">${['🧡','👀','💡','😂','🚨','✨','💥','🎬','☕'].map(value=>`<option value="${value}">${value}</option>`).join('')}</select></div><div class="field"><label>Post-it</label><select name="style"><option value="orange">Laranja</option><option value="light">Claro</option><option value="dark">Preto</option><option value="outline">Contorno</option></select></div></div><button class="btn pri">Colar no mural</button></form></details></section><div class="mural-board-wrap v555-board-wrap"><div class="mural-board" style="min-height:${Math.max(520,70+Math.ceil(Math.max(active.length,1)/3)*205)}px">${active.map(muralNoteCard).join('')||'<div class="mural-empty"><b>O mural está livre.</b><br><small>O próximo recado pode começar aqui.</small></div>'}</div></div>${done.length?`<section class="panel mural-done"><div class="head"><div><small class="ey">RESOLVIDOS</small><h3>Arquivo do mural</h3></div><span class="tag">${done.length}</span></div>${done.map(note=>`<div class="row"><span>${E(note.emoji||'✓')}</span><div class="grow"><b>${E(note.body)}</b><small>${E(profile(note.author_id)?.display_name||'Equipe')}</small></div><button class="btn ghost small" data-muralrestore="${note.id}">Voltar ao mural</button></div>`).join('')}</section>`:''}`
};

let muralSyncTimerV555=null,muralSyncBusyV555=false;
async function syncMuralV555(){
  if(muralSyncBusyV555||V!=='mural'||M?.role!=='team'||!S?.user?.id)return;
  muralSyncBusyV555=true;
  try{
    let [memberships,profiles,statuses,notes]=await Promise.all([
      api('/rest/v1/user_memberships?select=user_id,role&role=eq.team&organization_id=eq.'+M.organization_id),
      api('/rest/v1/member_profiles?select=*&organization_id=eq.'+M.organization_id+'&order=display_name'),
      api('/rest/v1/team_statuses?select=*&organization_id=eq.'+M.organization_id+'&order=updated_at.desc'),
      api('/rest/v1/mural_notes?select=*&organization_id=eq.'+M.organization_id+'&order=pinned.desc,updated_at.desc')
    ]);
    let before=JSON.stringify([D.teamMemberships,D.profiles,D.teamStatuses,D.muralNotes]);
    D.teamMemberships=memberships||[];D.profiles=profiles||[];D.teamStatuses=statuses||[];D.muralNotes=notes||[];
    if(before!==JSON.stringify([D.teamMemberships,D.profiles,D.teamStatuses,D.muralNotes])&&V==='mural'&&!MD)render();
  }catch(error){console.warn('Sincronização do mural',error)}finally{muralSyncBusyV555=false}
}
function muralSyncLifecycleV555(){
  if(V==='mural'&&M?.role==='team'){
    if(!muralSyncTimerV555)muralSyncTimerV555=setInterval(syncMuralV555,10000);
  }else if(muralSyncTimerV555){clearInterval(muralSyncTimerV555);muralSyncTimerV555=null}
}
