const _bindMuralDragV555Base=bindMuralDrag;
bindMuralDrag=function(){if(window.matchMedia('(max-width:760px)').matches)return;_bindMuralDragV555Base()};
window.addEventListener('focus',()=>{if(V==='mural')syncMuralV555()});
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&V==='mural')syncMuralV555()});

