labGenerateContentV560=async function(useStructure=false){
  let state=labStateV560(),topic=labCaptureTopicV560();if(!topic){state.error='Escreva um tema ou selecione uma pauta antes de criar.';render();return}
  let structure=useStructure?labCaptureStructureV560():null;state.busy='content';state.error='';state.stage='content-loading';render();
  try{
    let payload=await labAIRequestV560('content',{topic,structure,pauta:state.selectedPauta});
    payload.slides=labSafeSlidesV560(payload);if(state.format==='reel'){if(!Array.isArray(payload.roteiro)||!payload.roteiro.length)throw Error('O roteiro voltou sem cenas. Tente novamente.')}else if(!payload.slides.length)throw Error('A criação voltou sem telas. Tente novamente.');
    state.result=payload;state.stage='result';state.history.unshift({result:JSON.parse(JSON.stringify(payload)),format:state.format,style:state.style,topic});if(state.history.length>8)state.history.pop()
  }catch(error){state.error=error.message;state.stage=structure?'structure':'empty'}finally{state.busy='';render()}
};
labCopyV560=function(){
  let state=labStateV560(),result=state.result||{},blocks=[result.titulo?`TÍTULO\n${result.titulo}`:'',result.angulo?`ÂNGULO\n${result.angulo}`:''];
  if(state.format==='reel')blocks.push('ROTEIRO\n'+(result.roteiro||[]).map((scene,index)=>[`Cena ${index+1}${scene.duracao?' · '+scene.duracao:''}`,scene.imagem?'Imagem: '+scene.imagem:'',scene.fala?'Fala/narração: '+scene.fala:'',scene.texto_tela?'Texto na tela: '+scene.texto_tela:''].filter(Boolean).join('\n')).join('\n\n'));
  else blocks.push(...labSafeSlidesV560(result).map((row,index)=>`TELA ${index+1} — ${row.rotulo}\n${row.texto_curto}`));
  if(result.capa)blocks.push(`CAPA\n${result.capa.titulo||''}${result.capa.apoio?'\n'+result.capa.apoio:''}${result.capa.direcao_visual?'\nDireção: '+result.capa.direcao_visual:''}`);if(result.direcao)blocks.push(`DIREÇÃO\nExecução: ${result.direcao.execucao||''}\nÁudio: ${result.direcao.audio||''}\nEdição: ${result.direcao.edicao||''}`);if(result.legenda)blocks.push(`LEGENDA\n${result.legenda}`);if(result.cta)blocks.push(`CTA\n${result.cta}`);
  navigator.clipboard?.writeText(blocks.filter(Boolean).join('\n\n')).then(()=>toast('Conteúdo completo copiado')).catch(()=>toast('Não foi possível copiar automaticamente'))
};
labSaveResultV560=async function(){
  let state=labStateV560(),result=state.result;if(!result)return;if(result.savedId){contentMode='workflow';render();return}state.busy='save';state.error='';render();
  try{
    let plan=await ensurePlan(contentClient,contentMonth),pillars=labPillarsV560(contentClient),pillarName=result.pilar||state.selectedPauta?.pilar||'',matched=pillars.find(row=>String(row.name).toLowerCase()===String(pillarName).toLowerCase())||pillars[0],script='';
    if(state.format==='reel')script=(result.roteiro||[]).map((scene,index)=>[`Cena ${index+1}${scene.duracao?' · '+scene.duracao:''}`,scene.imagem?'Imagem: '+scene.imagem:'',scene.fala?'Fala/narração: '+scene.fala:'',scene.texto_tela?'Texto na tela: '+scene.texto_tela:''].filter(Boolean).join('\n')).join('\n\n');else script=labSafeSlidesV560(result).map((row,index)=>`Tela ${index+1} — ${row.rotulo}\n${row.texto_curto}`).join('\n\n');
    let direction=result.direcao?`\n\nDIREÇÃO DE PRODUÇÃO\nExecução: ${result.direcao.execucao||''}\nÁudio: ${result.direcao.audio||''}\nEdição: ${result.direcao.edicao||''}`:'',cover=result.capa?`\n\nCAPA\n${result.capa.titulo||''}${result.capa.apoio?'\n'+result.capa.apoio:''}${result.capa.direcao_visual?'\nDireção visual: '+result.capa.direcao_visual:''}`:'',referenceLinks=contentReferencesV561(contentClient).filter(row=>row.source_url).map(row=>row.source_url).slice(0,12);
    let rows=await api('/rest/v1/contents',{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify({organization_id:M.organization_id,client_id:contentClient,title:result.titulo||state.topic,format:labFormatDbV560(state.format),objective:result.objetivo||state.topic||null,central_idea:result.angulo||state.topic||null,script:(script+cover+direction).trim()||null,caption:result.legenda||null,cta:result.cta||state.structure?.cta||null,editorial_pillar_id:matched?.id||null,monthly_plan_id:plan?.id||null,status:'idea',reference_links:referenceLinks,created_by:S.user?.id,internal_notes:'Criado no Laboratório de Conteúdo com o DNA da cliente · '+labStyleLabelV560(state.style)})});
    let content=rows?.[0];if(!content?.id)throw Error('O conteúdo foi criado, mas não retornou para o fluxo.');result.savedId=content.id;
    try{await api('/rest/v1/content_team_workflow',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({organization_id:M.organization_id,client_id:contentClient,content_id:content.id,internal_status:'draft',internal_notes:'Conteúdo completo criado no Laboratório. Revisar roteiro, capa, legenda e direção visual antes do design.',created_by:S.user?.id})})}catch(error){console.warn('Workflow do Laboratório',error)}
    await load();contentMode='workflow';render();toast('Conteúdo completo salvo no workflow ✦')
  }catch(error){state.error=error.message;state.busy='';state.stage='result';render()}
};

